// ---- §owner TEXTURE PIPELINE ---------------------------------------------
//
// Every surface in this world was a flat colour. That is the single
// biggest thing holding the look back: shape and lighting were doing all
// the work, so a wall, a crate and the ground differed only in hue.
//
// The textures are GENERATED, not loaded. There is no texture art in
// this project, and inventing a dependency on files that do not exist
// would block the whole feature on an art pass. Procedural noise costs
// nothing at build time, ships inside the binary, and - because every
// generator here is a pure function of a seed - is bit-identical on
// every machine, which matters for a capture harness that compares
// frames.
//
// All of it is COSMETIC. No texture is ever read by `sim`.

/// Side of every generated texture. Small on purpose: these tile, and a
/// 128px tile that repeats convincingly beats a 1024px one that costs
/// memory to say the same thing at this art style's fidelity.
const TEX_SIZE: u32 = 128;

/// A deterministic value-noise hash in 0..1, seeded per texture.
///
/// Deliberately its own tiny hash rather than the sim's `Pcg32`: this
/// runs at startup on the render side and must never touch the
/// simulation's RNG stream, or generating a texture would move where
/// bullets go.
fn tex_hash(x: u32, y: u32, seed: u32) -> f32 {
    let mut h = x
        .wrapping_mul(0x27d4_eb2d)
        ^ y.wrapping_mul(0x1656_67b1)
        ^ seed.wrapping_mul(0x9e37_79b9);
    h ^= h >> 15;
    h = h.wrapping_mul(0x85eb_ca6b);
    h ^= h >> 13;
    (h & 0xffff) as f32 / 65535.0
}

/// Smoothed noise at a given cell size, wrapping at the tile edge so the
/// texture repeats seamlessly - a tile with a visible seam is worse than
/// no texture at all.
fn tex_noise(x: u32, y: u32, cells: u32, seed: u32) -> f32 {
    let cells = cells.max(1);
    let step = (TEX_SIZE / cells).max(1);
    let (gx, gy) = (x / step, y / step);
    let (fx, fy) = (
        (x % step) as f32 / step as f32,
        (y % step) as f32 / step as f32,
    );
    // smoothstep, for a soft interpolation rather than a linear ramp
    let (sx, sy) = (fx * fx * (3.0 - 2.0 * fx), fy * fy * (3.0 - 2.0 * fy));
    let w = |a: u32, b: u32| tex_hash(a % cells, b % cells, seed);
    let (a, b) = (w(gx, gy), w(gx + 1, gy));
    let (c, d) = (w(gx, gy + 1), w(gx + 1, gy + 1));
    let top = a + (b - a) * sx;
    let bot = c + (d - c) * sx;
    top + (bot - top) * sy
}

/// Several octaves of the above - the standard trick that turns flat
/// noise into something that reads as a material.
fn tex_fbm(x: u32, y: u32, seed: u32) -> f32 {
    let mut v = 0.0;
    let mut amp = 0.5;
    let mut cells = 4;
    for o in 0..4 {
        v += tex_noise(x, y, cells, seed.wrapping_add(o * 977)) * amp;
        amp *= 0.5;
        cells *= 2;
    }
    v.clamp(0.0, 1.0)
}

/// Build a tiling texture from a per-pixel closure returning a
/// brightness multiplier in 0..1, where 1.0 means "leave this texel
/// alone".
///
/// The base colour stays on the MATERIAL, so one generator serves every
/// tint: the texture supplies structure, the material supplies colour.
/// That is why these are all grey.
///
/// The generators therefore run DARK-SIDE ONLY - they shade downward
/// from white and never above it. The first cut centred them on 1.0 and
/// encoded that as mid-grey, which silently halved the brightness of
/// every surface it touched and washed the variation out to nothing.
fn make_tex(images: &mut Assets<Image>, f: impl Fn(u32, u32) -> f32) -> Handle<Image> {
    use bevy::image::{ImageAddressMode, ImageSampler, ImageSamplerDescriptor};
    use bevy::render::render_asset::RenderAssetUsages;
    use bevy::render::render_resource::{Extent3d, TextureDimension, TextureFormat};
    let mut data = Vec::with_capacity((TEX_SIZE * TEX_SIZE * 4) as usize);
    for y in 0..TEX_SIZE {
        for x in 0..TEX_SIZE {
            let v = (f(x, y).clamp(0.0, 1.0) * 255.0) as u8;
            data.extend_from_slice(&[v, v, v, 255]);
        }
    }
    let mut img = Image::new(
        Extent3d {
            width: TEX_SIZE,
            height: TEX_SIZE,
            depth_or_array_layers: 1,
        },
        TextureDimension::D2,
        data,
        // Unorm, NOT Srgb: this is a multiplier against base_color, and
        // running it through an sRGB decode would darken every surface
        // it touches rather than modulating it.
        TextureFormat::Rgba8Unorm,
        RenderAssetUsages::RENDER_WORLD,
    );
    // These tile across large surfaces. Without Repeat the sampler
    // clamps and a single edge texel smears across a whole wall.
    img.sampler = ImageSampler::Descriptor(ImageSamplerDescriptor {
        address_mode_u: ImageAddressMode::Repeat,
        address_mode_v: ImageAddressMode::Repeat,
        ..ImageSamplerDescriptor::linear()
    });
    images.add(img)
}

/// Build a NORMAL MAP from the same height field that drives an albedo
/// texture, by central differences (a Sobel-lite).
///
/// This is what turns colour variation into apparent DEPTH: mortar
/// courses catch a shadow on one side, plank seams read as grooves, and
/// the brushed metal picks up a direction. The albedo alone could only
/// ever make a surface look painted.
///
/// Two things are load-bearing and easy to get wrong:
/// - the format MUST stay linear (`Rgba8Unorm`). A normal map decoded as
///   sRGB is a wrong vector at every texel, which reads as blotchy
///   lighting rather than as an obvious error.
/// - the mesh MUST carry tangents, or Bevy silently declines to apply
///   this at all. See `with_tangents` at the mesh sites.
fn make_normal_tex(
    images: &mut Assets<Image>,
    strength: f32,
    height: impl Fn(u32, u32) -> f32,
) -> Handle<Image> {
    use bevy::image::{ImageAddressMode, ImageSampler, ImageSamplerDescriptor};
    use bevy::render::render_asset::RenderAssetUsages;
    use bevy::render::render_resource::{Extent3d, TextureDimension, TextureFormat};
    let w = |x: i64, y: i64| -> f32 {
        // wrap, so the normal map tiles as seamlessly as its albedo
        let xi = x.rem_euclid(TEX_SIZE as i64) as u32;
        let yi = y.rem_euclid(TEX_SIZE as i64) as u32;
        height(xi, yi)
    };
    let mut data = Vec::with_capacity((TEX_SIZE * TEX_SIZE * 4) as usize);
    for y in 0..TEX_SIZE as i64 {
        for x in 0..TEX_SIZE as i64 {
            let dx = (w(x + 1, y) - w(x - 1, y)) * strength;
            let dy = (w(x, y + 1) - w(x, y - 1)) * strength;
            // the surface normal of a heightfield: (-dh/dx, -dh/dy, 1)
            let (nx, ny, nz) = (-dx, -dy, 1.0_f32);
            let len = (nx * nx + ny * ny + nz * nz).sqrt().max(1e-6);
            let enc = |v: f32| (((v / len) * 0.5 + 0.5).clamp(0.0, 1.0) * 255.0) as u8;
            data.extend_from_slice(&[enc(nx), enc(ny), enc(nz), 255]);
        }
    }
    let mut img = Image::new(
        Extent3d {
            width: TEX_SIZE,
            height: TEX_SIZE,
            depth_or_array_layers: 1,
        },
        TextureDimension::D2,
        data,
        TextureFormat::Rgba8Unorm,
        RenderAssetUsages::RENDER_WORLD,
    );
    img.sampler = ImageSampler::Descriptor(ImageSamplerDescriptor {
        address_mode_u: ImageAddressMode::Repeat,
        address_mode_v: ImageAddressMode::Repeat,
        ..ImageSamplerDescriptor::linear()
    });
    images.add(img)
}

/// The generated surface set. Structure only - every one of these is
/// grey and takes its colour from whatever material mounts it.
#[derive(Resource, Clone)]
struct TextureKit {
    /// wind-rippled dirt with scattered grit
    ground: Handle<Image>,
    /// coarse blockwork with offset courses and mortar lines
    stone: Handle<Image>,
    /// straight grain with occasional knots
    wood: Handle<Image>,
    /// fine brushed grain with a few deeper scratches
    metal: Handle<Image>,
    /// Matching normal maps, generated from the SAME height functions -
    /// so the bumps line up with the colour rather than being a second
    /// pattern laid over the first.
    ground_n: Handle<Image>,
    stone_n: Handle<Image>,
    wood_n: Handle<Image>,
    metal_n: Handle<Image>,
}

/// The four height fields, named once and shared.
///
/// Albedo and normal are generated from the SAME function per surface -
/// that is the whole reason these are hoisted out rather than written
/// inline at each `make_tex` call. Two copies would drift, and a normal
/// map whose bumps do not line up with its own colour looks worse than
/// no normal map at all.
fn height_ground(x: u32, y: u32) -> f32 {
    let broad = tex_fbm(x, y, 11);
    let grit = tex_hash(x, y, 733);
    // fbm clusters hard around its own mean, so raw it produced a band
    // far too narrow to see once lit - a checkerboard diagnostic proved
    // the texture was binding and tiling correctly all along and only
    // the CONTRAST was wrong. Pushed out from the midpoint before use.
    let broad = ((broad - 0.5) * 2.4 + 0.5).clamp(0.0, 1.0);
    // patches of packed dirt against looser sand, at a scale bigger than
    // one tile's noise so the ground does not read as uniform fuzz
    let patch = if tex_noise(x, y, 3, 401) > 0.58 { 0.86 } else { 1.0 };
    ((0.55 + broad * 0.45) * patch + grit * 0.06).min(1.0)
}

/// Mortar courses every quarter tile, offset row to row so it reads as
/// laid blockwork rather than a grid, with noise over the faces so no
/// two blocks match.
fn height_stone(x: u32, y: u32) -> f32 {
    let block = TEX_SIZE / 4;
    let row = y / block;
    let shift = if row % 2 == 0 { 0 } else { block / 2 };
    let bx = (x + shift) % block;
    let by = y % block;
    let mortar = bx < 3 || by < 3;
    let body = 0.74 + tex_fbm(x, y, 29) * 0.26;
    if mortar {
        body * 0.55 // the joint reads as a real recess
    } else {
        body
    }
}

/// Grain along one axis, warped by noise so it is grain and not stripes,
/// with the odd darker knot.
fn height_wood(x: u32, y: u32) -> f32 {
    let n = TEX_SIZE as f32;
    let warp = tex_fbm(x, y, 53) * 12.0;
    let rings = (((y as f32 + warp) / n * 22.0).sin() * 0.5 + 0.5).powf(1.6);
    let knot = if tex_noise(x, y, 6, 91) > 0.86 { 0.62 } else { 1.0 };
    ((0.66 + rings * 0.34) * knot).min(1.0)
}

/// Fine horizontal brushing, plus a few deeper scratches.
fn height_metal(x: u32, y: u32) -> f32 {
    let brush = tex_hash(x / 2, y, 137) * 0.12;
    let scratch = if tex_noise(x, y, 3, 211) > 0.90 { 0.80 } else { 1.0 };
    ((0.84 + brush) * scratch).min(1.0)
}

fn build_texture_kit(images: &mut Assets<Image>) -> TextureKit {
    // Normal strengths are per-surface on purpose: mortar joints are a
    // real recess and want to read hard, brushed metal is microscopic
    // and wants to read as sheen rather than as corrugation.
    TextureKit {
        ground: make_tex(images, height_ground),
        stone: make_tex(images, height_stone),
        wood: make_tex(images, height_wood),
        metal: make_tex(images, height_metal),
        ground_n: make_normal_tex(images, 2.4, height_ground),
        stone_n: make_normal_tex(images, 6.0, height_stone),
        wood_n: make_normal_tex(images, 3.0, height_wood),
        metal_n: make_normal_tex(images, 1.4, height_metal),
    }
}

/// Shared meshes + materials for building weapon / gear models.
#[derive(Resource, Clone)]
struct ModelKit {
    cube: Handle<Mesh>,
    cyl: Handle<Mesh>, // unit cylinder: radius 0.5, height 1, axis Y
    ball: Handle<Mesh>, // unit sphere: radius 0.5
    gunmetal: Handle<StandardMaterial>,
    steel: Handle<StandardMaterial>,
    wood: Handle<StandardMaterial>,
    string: Handle<StandardMaterial>,
    lens: Handle<StandardMaterial>,
    olive: Handle<StandardMaterial>,
    gold: Handle<StandardMaterial>,
    white: Handle<StandardMaterial>,
    med_glow: Handle<StandardMaterial>,
    /// §owner MECH WEAPON LOOK: the repair beam's translucent GREEN
    /// sheath, and the bloom where it lands.
    ///
    /// These exist because the repair beam had no colour of its own. It
    /// drew its shaft with `barrier_edge` (the SHIELD film's blue) and
    /// its travelling packets with `core_glow` (the DANGER red) - so the
    /// one thing on this battlefield that means "I am mending you"
    /// rendered as a shield-coloured bar carrying red warning lights,
    /// which is two other signals and neither of them healing. `med_glow`
    /// was already the friendly repair green and was already in the kit;
    /// nothing was missing but the wiring.
    ///
    /// Two layers for the same reason `plasma_core`/`plasma_halo` are
    /// two: the packet is near-white at the middle because a hot thing
    /// is, and the hue lives in the sheath around it.
    repair_sheath: Handle<StandardMaterial>,
    repair_bloom: Handle<StandardMaterial>,
    armor_dark: Handle<StandardMaterial>,
    core_glow: Handle<StandardMaterial>,
    /// §owner the plasma bolt's two layers. The CORE is nearly white -
    /// a hot thing is white at the middle, not saturated - and the
    /// HALO around it carries the colour. One material would have to
    /// choose, and choosing gives you either a pale streak with no hue
    /// or a coloured stick with no heat.
    plasma_core: Handle<StandardMaterial>,
    plasma_halo: Handle<StandardMaterial>,
    /// §25 the GREEN armour-impact flash. A separate pair from the
    /// medic's plasma bolt on purpose: that one is a projectile the
    /// player tracks in flight, this one is a hit confirmation, and two
    /// things that mean different things must not share a colour.
    hit_plasma_core: Handle<StandardMaterial>,
    hit_plasma_halo: Handle<StandardMaterial>,
    /// the gripping mitt - §1 restyles this to the robot's shell
    hand: Handle<StandardMaterial>,
    // §2.1 weapon palette: four flat greys, tone changes - not geometry -
    // suggest complexity (the reference's rail notches are tone stripes)
    grey_light: Handle<StandardMaterial>,
    grey_mid: Handle<StandardMaterial>,
    grey_dark: Handle<StandardMaterial>,
    grey_black: Handle<StandardMaterial>,
    /// §owner BOW & SPEAR: the two materials the tackle palette needed
    /// and the four greys could not supply. `wood` and `string` already
    /// existed above and are reused rather than duplicated - see `Tone`.
    leather: Handle<StandardMaterial>,
    blade: Handle<StandardMaterial>,
    collar: Handle<StandardMaterial>,
    // §11 (Brief IV): the Mech Armada palette - khaki faceted plates
    // over shadowed joints, one red sensor slit
    mech_khaki: Handle<StandardMaterial>,
    mech_khaki_dk: Handle<StandardMaterial>,
    mech_khaki_lt: Handle<StandardMaterial>,
    /// §22 THE ROYAL VARIANT's three body tones. Exactly the three the
    /// heavy already paints itself with, so the variant is a swap of
    /// handles at the top of `spawn_armor_rig` rather than a second copy
    /// of a 53-plate table - which is the only reason a third or fourth
    /// livery would ever be cheap enough to add.
    /// §P3: the PLAYER's Royal - deep bronze-graphite with gold. See the
    /// note at its construction for why it is not the spec's neon blue.
    mech_royal_ally: Handle<StandardMaterial>,
    mech_royal_ally_dk: Handle<StandardMaterial>,
    mech_royal_ally_lt: Handle<StandardMaterial>,
    /// The OPPOSITION Royal - dark red lacquer with a hot red highlight.
    mech_royal: Handle<StandardMaterial>,
    mech_royal_dk: Handle<StandardMaterial>,
    mech_royal_lt: Handle<StandardMaterial>,
    /// §gallery THE ENEMY HEAVY's three body tones.
    ///
    /// The heavy shipped in ONE livery for both factions: two heavy
    /// mechs at range were the same machine in the same paint, and the
    /// only thing that said whose it was was the name plate over its
    /// head. That is the exact complaint the plate armour and the light
    /// chassis were both re-liveried to answer (see `plate_shell_foe`
    /// and `scout_hull_foe`), and the heaviest, largest silhouette in
    /// the game was the one that never got the fix.
    ///
    /// Same three roles as the khaki set, so it is a handle swap at the
    /// top of `spawn_armor_rig`.
    ///
    /// §owner BLUE ENEMY MECHS: "make enemy mechs colour dark blue and
    /// light blue tones, so the details should implemented". The three
    /// slots ARE the tone ladder, so the two blues map onto them with
    /// nothing invented:
    ///   `mech_navy`     BODY      dark blue     the big plate
    ///   `mech_navy_dk`  STRUCTURE deeper navy   housings, recesses
    ///   `mech_navy_lt`  DETAIL    light blue    edge strips, panel picks
    /// The lit accent is the fourth role and lives in `mech_lamp_foe`.
    ///
    /// This REPLACED a near-black oxide iron, and the swap costs the
    /// faction system nothing: the ally/enemy read is a LUMINANCE rule
    /// (`branding::signal`), the ally is the bright thing on the field,
    /// and a dark blue body is still dark. Only the hue moved.
    mech_navy: Handle<StandardMaterial>,
    mech_navy_dk: Handle<StandardMaterial>,
    mech_navy_lt: Handle<StandardMaterial>,
    mech_shadow: Handle<StandardMaterial>,
    mech_metal: Handle<StandardMaterial>,
    mech_red: Handle<StandardMaterial>,
    /// §gallery the ALLY heavy's lit accent - the mirror of `mech_lamp_foe`.
    ///
    /// Gold where the foe machine is red: the sensor slit, the pod
    /// status line and the two tracking lenses. The enemy machine wears
    /// `mech_lamp_foe` in the same three places, so the "one lit slit is
    /// the x2 weak point" read is identical on both sides.
    ///
    /// `unlit` exactly like `mech_lamp_foe`, which means the `emissive` on
    /// either is dead weight - Bevy's unlit path returns `base_color`
    /// and never reaches the emissive add. The brightness therefore
    /// lives in the base colour here, on purpose.
    mech_lamp: Handle<StandardMaterial>,
    /// §owner BLUE ENEMY MECHS: the ENEMY heavy's lit accent.
    ///
    /// The enemy machine used to borrow `mech_red` for its visor slit,
    /// pod status line and tracking lenses. `mech_red` still exists and
    /// still does its OTHER jobs (pod missiles in flight, the khaki
    /// weapon-attachment lenses), so this is a new handle rather than a
    /// recolour of that one - the two had been sharing a name for two
    /// different ideas.
    ///
    /// `unlit`, exactly like `mech_lamp`: Bevy's unlit path returns
    /// `base_color` and never reaches `emissive`, so ALL of the apparent
    /// brightness has to live in the base colour. A light blue chosen at
    /// panel luminance would read as a pale sticker rather than a lamp.
    mech_lamp_foe: Handle<StandardMaterial>,
    /// §4.2 (Brief VI): yellow-black hazard accents.
    mech_hazard: Handle<StandardMaterial>,
    /// FP-only translucent shield set - the raised plate must not blind
    /// the player. Third-person shields keep the opaque materials above.
    /// §owner MECH BARRIER: the near-invisible field body, and the bright
    /// cell edges drawn through it. See where they are built.
    barrier_fill: Handle<StandardMaterial>,
    barrier_edge: Handle<StandardMaterial>,
    /// §owner TEAM IDENTITY: the PLATE ARMOUR, per side.
    ///
    /// The 24-piece harness shipped in one fixed material set for both
    /// factions - so the single most visible thing a soldier wears said
    /// nothing about whose side he was on, and two plated men at range
    /// were the same silhouette in the same colours.
    ///
    /// Four roles, mirrored:
    ///   SHELL  the plate body      white / near-black iron
    ///   TRIM   the bright lip      gold  / red, emissive
    ///   STEEL  frames and cops     grey  / dark metal
    ///   RIVET  fasteners           dark on both, so the fine detail
    ///                              reads as shadow on either faction
    ///
    /// The trim is emissive on the ENEMY only. That asymmetry is the
    /// team-signal rule, not an oversight: allies are bright bodies with
    /// a warm accent, enemies are dark bodies with one GLOWING line, and
    /// a glow is what makes a near-black plate legible at all in the
    /// dust fog.
    plate_shell: Handle<StandardMaterial>,
    plate_shell_foe: Handle<StandardMaterial>,
    plate_trim: Handle<StandardMaterial>,
    plate_trim_foe: Handle<StandardMaterial>,
    plate_steel: Handle<StandardMaterial>,
    plate_steel_foe: Handle<StandardMaterial>,
    /// §owner AGILE SUPPORT MECH: its own palette, per side.
    ///
    /// The light chassis does NOT wear the heavy's khaki. It is a
    /// different machine doing a different job and it should be
    /// identifiable before you can make out its shape - which is the
    /// same argument the team-signal palette already makes about
    /// soldiers, applied one level up to the class of machine.
    ///
    /// FRIENDLY reads service amber over a black frame with gold light
    /// lines; ENEMY reads §owner-blue - dark blue shell, light blue
    /// detail plates, hot blue lines. Both keep the SAME silhouette and
    /// the same emissive placement, so what changes at a distance is the
    /// hue and never the shape - a player should be able to tell friend
    /// from foe without having to identify the model first.
    scout_hull: Handle<StandardMaterial>,
    scout_hull_foe: Handle<StandardMaterial>,
    scout_plate: Handle<StandardMaterial>,
    scout_plate_foe: Handle<StandardMaterial>,
    scout_line: Handle<StandardMaterial>,
    scout_line_foe: Handle<StandardMaterial>,
    /// BRIEF X §2, the roles the old two-tone light chassis had no name
    /// for. `agile_blue` is the METALLIC BLUE MACHINERY - joints, inner
    /// structure, mechanical limb sections, connectors, weapon mounts.
    /// `agile_energy` is the SUBTLE BRIGHT BLUE TECHNOLOGY, and it is a
    /// single material shared by both sides on purpose: it is a
    /// technology colour, not a livery colour, and the friend-or-foe
    /// signal stays on `scout_line`/`scout_line_foe` where it already
    /// was. See `agile_mech::Livery`.
    agile_blue: Handle<StandardMaterial>,
    agile_blue_foe: Handle<StandardMaterial>,
    agile_energy: Handle<StandardMaterial>,
    vm_shield_dark: Handle<StandardMaterial>,
    vm_shield_steel: Handle<StandardMaterial>,
    vm_shield_gold: Handle<StandardMaterial>,
    /// Faded unit-stencil paint for the mech ident plates - decorative
    /// parchment, deliberately dimmer than the ally signal white.
    mech_stencil: Handle<StandardMaterial>,
    /// The 1x optic reticle - unlit so it holds its glow in shadow, the
    /// way a real illuminated dot does.
    optic_red: Handle<StandardMaterial>,
}

/// §2.1 tone slots of the weapon palette.
#[derive(Clone, Copy, PartialEq, Debug)]
enum Tone {
    Light,
    Mid,
    Dark,
    Black,
    /// The red-dot RETICLE - unlit emissive red, the only non-grey in
    /// the weapon palette. Deliberately its own slot rather than a
    /// reuse of `mech_red`: that one is a gameplay PROMISE (the visor
    /// weak point carries MECH_VISOR_MULT), and a reticle that shared
    /// its handle would start reading as a hit marker.
    Reticle,
    // ---- §owner BOW & SPEAR: the TACKLE palette ----------------------
    //
    // The four greys are a FIREARM vocabulary - flat machined metal in
    // four values - and the bow and the spear are not firearms. Built
    // out of that palette the war bow photographed as a black post with
    // a grey wire across it (`handback/brief-vii/bow_draw_fp`, the
    // frames dated before this pass), which is what the owner was
    // looking at when they asked for "warm mid-brown wood, a slim black
    // leather grip, a pale taut string".
    //
    // Four more slots, and they are MATERIALS rather than values: wood
    // has grain, leather is matte and near-black, cord is pale and
    // unmetallic, and a forged blade is dark. The handles behind them
    // already existed (`kit.wood`, `kit.string`) and two of them had no
    // reader at all - the bowstring material has been built every
    // startup since the bow shipped and drawn on nothing.
    /// Warm mid-brown, grained. Bow limbs and riser core, spear shaft,
    /// arrow shaft - the same stick in all three places, on purpose.
    Wood,
    /// Near-black matte leather. The bow's grip wrap only.
    Leather,
    /// Pale, unmetallic cord. The bowstring.
    Cord,
    /// Dark forged steel. Spear blade and arrow head - a war head is
    /// dark iron, not the bright `Light` grey a receiver is.
    Blade,
    /// The short red binding that seats a blade on a shaft.
    Collar,
}

impl ModelKit {
    fn tone(&self, t: Tone) -> Handle<StandardMaterial> {
        match t {
            Tone::Light => self.grey_light.clone(),
            Tone::Mid => self.grey_mid.clone(),
            Tone::Dark => self.grey_dark.clone(),
            Tone::Black => self.grey_black.clone(),
            Tone::Reticle => self.optic_red.clone(),
            Tone::Wood => self.wood.clone(),
            Tone::Leather => self.leather.clone(),
            Tone::Cord => self.string.clone(),
            Tone::Blade => self.blade.clone(),
            Tone::Collar => self.collar.clone(),
        }
    }
}

/// §2.1 shared part vocabulary: every gun is blocks + cylinders in the
/// four-grey palette. Local frame: root at the grip, muzzle-forward = +Z
/// (the bow stands along +Y with its string toward −Z).
struct WPart {
    cyl: bool,
    tone: Tone,
    pos: Vec3,
    /// radians about X - magazines and stocks are raked, never square
    tilt: f32,
    size: Vec3,
    /// true → ADS-only greeble (rides the existing detail-LOD path)
    detail: bool,
    /// true → hangs off the SPINNER child instead of the model root.
    ///
    /// Only the minigun's barrel cluster. A flag on the PART rather than a
    /// hand-written spawn chain, because that chain was the single thing
    /// keeping this whole vocabulary trapped inside a function that needs
    /// `Commands` - see `weapon_parts`.
    spin: bool,
}

impl WPart {
    /// Half-extents in the weapon's own frame, after `tilt`.
    ///
    /// `tilt` rotates about X, so the X half-extent is untouched and Y and
    /// Z mix. This is the AABB of the rotated box - a BOUND, not the exact
    /// silhouette, and conservative on purpose: a budget that
    /// over-estimates a part fails safe, one that under-estimates it lets
    /// geometry through.
    ///
    /// A cylinder is bounded by its own box for the same reason. Bevy's
    /// cylinder is Y-aligned before `tilt`, so that box is already the
    /// right shape to contain it.
    fn half(&self) -> Vec3 {
        let (s, c) = (self.tilt.sin().abs(), self.tilt.cos().abs());
        let h = self.size.abs() * 0.5;
        Vec3::new(h.x, h.y * c + h.z * s, h.y * s + h.z * c)
    }
}

fn wp(cyl: bool, tone: Tone, pos: (f32, f32, f32), tilt: f32, size: (f32, f32, f32)) -> WPart {
    WPart {
        cyl,
        tone,
        pos: Vec3::new(pos.0, pos.1, pos.2),
        tilt,
        size: Vec3::new(size.0, size.1, size.2),
        detail: false,
        spin: false,
    }
}

fn wd(cyl: bool, tone: Tone, pos: (f32, f32, f32), tilt: f32, size: (f32, f32, f32)) -> WPart {
    WPart {
        detail: true,
        ..wp(cyl, tone, pos, tilt, size)
    }
}

/// A part on the SPINNER - the minigun's barrel cluster, and nothing else.
fn ws(cyl: bool, tone: Tone, pos: (f32, f32, f32), tilt: f32, size: (f32, f32, f32)) -> WPart {
    WPart {
        spin: true,
        ..wp(cyl, tone, pos, tilt, size)
    }
}

/// The reference's signature top rail: a repeated notch pattern -
/// alternating light/mid blocks over a dark base bar.
fn push_rail(parts: &mut Vec<WPart>, y: f32, z0: f32, z1: f32, n: usize) {
    parts.push(wp(false, Tone::Dark, (0.0, y, (z0 + z1) * 0.5), 0.0, (0.030, 0.018, z1 - z0)));
    let step = (z1 - z0) / n as f32;
    for i in 0..n {
        let tone = if i % 2 == 0 { Tone::Light } else { Tone::Mid };
        parts.push(wp(
            false,
            tone,
            (0.0, y + 0.014, z0 + step * (i as f32 + 0.5)),
            0.0,
            (0.034, 0.012, step * 0.55),
        ));
    }
}

/// Skeletal stock: an OUTLINE of thin bars with a hole through it, never
/// a solid block - top bar, bottom bar, rear vertical, shoulder pad.
fn push_stock(parts: &mut Vec<WPart>, z_rear: f32, drop: f32) {
    let len = -z_rear - 0.04; // grip → rear
    let zc = z_rear * 0.5 - 0.02;
    parts.push(wp(false, Tone::Dark, (0.0, 0.035, zc), 0.06, (0.024, 0.024, len)));
    parts.push(wp(false, Tone::Dark, (0.0, -drop, zc), -0.10, (0.024, 0.024, len)));
    parts.push(wp(false, Tone::Dark, (0.0, (0.035 - drop) * 0.5, z_rear), 0.0, (0.026, drop + 0.10, 0.028)));
    parts.push(wp(false, Tone::Mid, (0.0, (0.035 - drop) * 0.5, z_rear - 0.018), 0.0, (0.030, drop + 0.13, 0.014)));
}

// ---- §owner GUN PASS: the shared surface vocabulary ---------------------
//
// Every firearm in the game was a stack of smooth boxes. At the ranges
// a viewmodel is seen from that reads as unfinished, and in third
// person it reads as nothing at all - a grey wedge.
//
// The fix is the same one the mech hull got: not MORE boxes, but the
// features that tell you a box is a machined part. A real gun's surface
// is panel breaks, fastener heads, cut-outs, and the places a hand or a
// magazine goes. Five helpers, so every weapon gets the same vocabulary
// and the arsenal reads as one armoury rather than ten separate props.
//
// All of it is `wp` (always-on) rather than `wd` (ADS-only): the
// complaint was that guns look bad in BOTH views, and detail that only
// appears when you aim does nothing for the third-person read.

/// A machined PANEL LINE - a thin dark recess along the receiver flank.
///
/// The single highest-value greeble on a box: a slab with a groove in it
/// stops being a slab, because the eye reads the shadow as a seam
/// between two parts.
fn push_panel_line(parts: &mut Vec<WPart>, y: f32, z0: f32, z1: f32, half_w: f32) {
    parts.push(wp(
        false,
        Tone::Black,
        (0.0, y, (z0 + z1) * 0.5),
        0.0,
        (half_w * 2.0 + 0.002, 0.005, z1 - z0),
    ));
}

/// FASTENER HEADS along a line - the pins and screws that hold a
/// receiver together. Small, dark, evenly spaced.
fn push_bolts(parts: &mut Vec<WPart>, x: f32, y: f32, z0: f32, z1: f32, n: usize) {
    for i in 0..n {
        let t = if n == 1 { 0.5 } else { i as f32 / (n - 1) as f32 };
        for sx in [-1.0_f32, 1.0] {
            parts.push(wp(
                false,
                Tone::Black,
                (sx * x, y, z0 + (z1 - z0) * t),
                0.0,
                (0.004, 0.011, 0.011),
            ));
        }
    }
}

/// The EJECTION PORT and its charging handle - the two features that
/// say which way a gun cycles, and the ones a player is most used to
/// seeing on the right-hand side of a receiver.
fn push_ejection_port(parts: &mut Vec<WPart>, x: f32, y: f32, z: f32, len: f32) {
    // the cut-out itself: dark, inset
    parts.push(wp(false, Tone::Black, (x, y, z), 0.0, (0.006, 0.030, len)));
    // its lower lip, catching light
    parts.push(wp(false, Tone::Light, (x, y - 0.020, z), 0.0, (0.007, 0.006, len)));
    // charging handle, back and up from the port
    parts.push(wp(false, Tone::Mid, (x * 1.25, y + 0.012, z - len * 0.75), 0.0, (0.022, 0.014, 0.036)));
}

/// A MAGAZINE's floorplate and witness slots - the underside a player
/// sees every time the gun tips during a reload.
fn push_mag_detail(parts: &mut Vec<WPart>, y_bot: f32, z: f32, w: f32, d: f32) {
    parts.push(wp(false, Tone::Black, (0.0, y_bot, z), 0.0, (w * 1.10, 0.010, d * 1.10)));
    parts.push(wp(false, Tone::Light, (0.0, y_bot - 0.006, z), 0.0, (w * 0.75, 0.006, d * 0.80)));
    // two witness slots up the body
    for k in 0..2 {
        parts.push(wp(
            false,
            Tone::Black,
            (w * 0.52, y_bot + 0.030 + k as f32 * 0.028, z),
            0.0,
            (0.004, 0.014, d * 0.45),
        ));
    }
}

/// FINGER GROOVES and a checkered face on a grip. A grip with no texture
/// reads as a handle; a grip with three grooves reads as one that was
/// designed around a hand.
fn push_grip_detail(parts: &mut Vec<WPart>, x_face: f32, y: f32, z: f32, tilt: f32) {
    for k in 0..3 {
        parts.push(wp(
            false,
            Tone::Black,
            (0.0, y - k as f32 * 0.026, z + 0.004),
            tilt,
            (x_face * 2.0 + 0.002, 0.006, 0.030),
        ));
    }
}

/// Muzzle device: a slightly wider dark block with a visible black bore
/// recess poking out of it.
fn push_muzzle(parts: &mut Vec<WPart>, y: f32, z: f32, w: f32) {
    parts.push(wp(false, Tone::Dark, (0.0, y, z), 0.0, (w, w, 0.07)));
    parts.push(wp(true, Tone::Black, (0.0, y, z + 0.028), FRAC_PI_2, (w * 0.45, 0.03, w * 0.45)));
}

/// §owner: where a FIRST-PERSON shot should visually leave from, in
/// camera-local space.
///
/// The sim casts every ray from the EYE - that is the hit test and it
/// must not move. But drawing the streak from there too puts the muzzle
/// flash in the middle of the screen, which reads as the player firing
/// out of their own face. It is most obvious in a mech, where the
/// mounts hang well off to one side of a very tall eye point.
///
/// These are the muzzle tips of the viewmodels as actually placed: the
/// mount carries in `setup`, plus the barrel/tube length from their
/// builders, times the 0.62/0.72 model scales. Kept next to `vm_carry`
/// so the two stay in view of each other.
fn fp_muzzle_local(p: &Fighter) -> Vec3 {
    if p.in_mech() {
        return match p.mech_weapon {
            // the launch tube: carry (0.19,-0.20,-0.46), tube runs to
            // local z 0.90 at scale 0.72
            sim::MechWeapon::Rockets => Vec3::new(0.19, -0.20, -0.46 - 0.90 * 0.72),
            // the gatling cluster - and the autocannon, which rides the
            // turret's viewmodel. Read off the model's OWN constants:
            // this used to be a hand-copied `-0.52 - 0.66 * 0.62`, and
            // the barrels have since moved twice.
            _ => Vec3::new(
                TURRET_VM_CARRY.x,
                TURRET_VM_CARRY.y,
                turret_vm_muzzle_camera_z(),
            ),
        };
    }
    // infantry: the carried gun's own offset, run forward to about the
    // end of a typical barrel at the shared 0.9 model scale
    let tr = vm_carry(p.gun).pos;
    Vec3::new(tr.x, tr.y, tr.z - 0.60 * 0.9)
}

/// Where the arrow's NOCK - the very back of the tail - sits in the arrow
/// model's own local space, per unit of `scale.z`.
///
/// Named because the BOW has to put this exact point on the string, and a
/// nocked arrow whose tail floats off the string, or buries through it, is
/// the first thing the eye catches on a drawn bow. It is the nock block's
/// centre (-0.345) less half its 0.03 length; `spawn_arrow_model` asserts
/// the two still agree.
const ARROW_NOCK_Z: f32 = -0.36;

/// §owner: a real ARROW in flight - forged head, tapered shaft, three
/// fletching vanes. It replaced a featureless 5 cm box, which at the
/// speeds this game looses arrows at read as a grey dash and told the
/// player nothing about which way it was going or where it would bite.
///
/// Built nose-forward along +Z in a UNIT-LENGTH envelope, so the
/// caller's `scale.z` sets the real length and the proportions hold.
/// The `spin` child carries the fletching alone - vanes rotate about
/// the shaft, a shaft that rolled as a whole would look like a drill.
/// §owner the plasma bolt, as geometry.
///
/// Built in the arrow's local frame - +Z is the direction of travel, and
/// the pool scales Z by the shaft length - so it drops into the same
/// slot without the caller learning a second convention.
///
/// Three ideas, in order of how far away they still read:
///   the HALO, a long translucent sheath that survives to the distance
///     where the core is one pixel;
///   the CORE, short and near-white, which is where the eye lands;
///   the WAKE, three shrinking rings behind it, which is the only part
///     that says which way the thing is going.
///
/// The wake is the load-bearing one. A symmetrical glowing capsule has
/// no heading, and a projectile whose heading you cannot read is a
/// projectile you cannot dodge - the bolt is slow enough (PLASMA_SPEED,
/// well under a rifle round) that dodging is a real thing a player does.
fn spawn_plasma_bolt_model(commands: &mut Commands, kit: &ModelKit) -> Entity {
    let root = commands
        .spawn((Transform::IDENTITY, Visibility::default()))
        .id();
    let mut part =
        |mesh: Handle<Mesh>, mat: Handle<StandardMaterial>, z: f32, rot: Quat, sc: Vec3| {
            commands
                .spawn((
                    Mesh3d(mesh),
                    MeshMaterial3d(mat),
                    Transform {
                        translation: Vec3::new(0.0, 0.0, z),
                        rotation: rot,
                        scale: sc,
                    },
                ))
                .set_parent(root);
        };
    // the sheath - longest, dimmest, and the whole silhouette at range
    part(kit.ball.clone(), kit.plasma_halo.clone(), 0.0, Quat::IDENTITY, Vec3::new(0.20, 0.20, 0.95));
    // the core - short and hot, sitting FORWARD of centre so the mass
    // reads at the leading end rather than in the middle of a capsule
    part(kit.ball.clone(), kit.plasma_core.clone(), 0.16, Quat::IDENTITY, Vec3::new(0.105, 0.105, 0.42));
    // the leading point: a small hard tip, because a bolt with a rounded
    // nose reads as floating and one with a point reads as travelling
    part(kit.cube.clone(), kit.plasma_core.clone(), 0.42, Quat::IDENTITY, Vec3::new(0.045, 0.045, 0.14));
    // the wake - three rings, each smaller and dimmer than the last.
    // A Bevy cylinder stands on Y, so every one of these is rotated a
    // quarter turn about X to FACE the direction of travel; left
    // unrotated they would be three discs lying flat through the bolt,
    // which is a different object entirely.
    for k in 0..3 {
        let t = k as f32;
        part(
            kit.cyl.clone(),
            kit.plasma_halo.clone(),
            -0.20 - t * 0.20,
            Quat::from_rotation_x(FRAC_PI_2),
            Vec3::new(0.17 - t * 0.045, 0.020, 0.17 - t * 0.045),
        );
    }
    root
}

fn spawn_arrow_model(commands: &mut Commands, kit: &ModelKit) -> (Entity, Entity) {
    debug_assert!(
        (ARROW_NOCK_Z - (-0.345 - 0.03 * 0.5)).abs() < 1e-6,
        "ARROW_NOCK_Z must track the nock block below"
    );
    let root = commands
        .spawn((Transform::IDENTITY, Visibility::default()))
        .id();
    // §owner THE ARROW: "a dark leaf/bodkin head, plain shaft matching
    // the bow's wood, modest fletching. Do not over-detail it. It must
    // read instantly in flight at gameplay distance."
    //
    // Five parts, and the count is the design. What changed from the
    // version before it is exactly two things: the head is DARK and
    // FLAT (it was a bright `steel` square section, which at 82 m/s
    // read as a grey pip on a grey dash), and the vanes are smaller.
    // The shaft is `kit.wood` - literally the bow's material handle,
    // so "matching the bow's wood" cannot come apart.
    for (mat, z, sc) in [
        (kit.wood.clone(), 0.02, Vec3::new(0.019, 0.019, 0.72)),
        // the leaf: wide and thin, so the head has an OUTLINE at range
        // rather than being a slightly fatter piece of shaft
        (kit.blade.clone(), 0.405, Vec3::new(0.026, 0.011, 0.085)),
        (kit.blade.clone(), 0.470, Vec3::new(0.011, 0.008, 0.055)),
        // the nock, so the tail reads as an arrow and not a cut stick
        (kit.grey_black.clone(), -0.345, Vec3::new(0.024, 0.024, 0.03)),
    ] {
        commands
            .spawn((
                Mesh3d(kit.cube.clone()),
                MeshMaterial3d(mat),
                Transform::from_xyz(0.0, 0.0, z).with_scale(sc),
            ))
            .set_parent(root);
    }
    // three fletching vanes on their own spinner
    let spin = commands
        .spawn((Transform::IDENTITY, Visibility::default()))
        .set_parent(root)
        .id();
    // MODEST: 0.038 tall where they were 0.048, and pulled in to a
    // 0.022 radius. Kept WHITE rather than dropped to the warm cord
    // tone - the vanes are the only bright thing on a dark-headed,
    // brown-shafted arrow, and brightness is what "reads instantly at
    // gameplay distance" actually buys.
    for i in 0..3 {
        let a = i as f32 * std::f32::consts::TAU / 3.0;
        commands
            .spawn((
                Mesh3d(kit.cube.clone()),
                MeshMaterial3d(kit.white.clone()),
                Transform {
                    translation: Vec3::new(a.cos() * 0.022, a.sin() * 0.022, -0.275),
                    rotation: Quat::from_rotation_z(a),
                    scale: Vec3::new(0.005, 0.038, 0.115),
                },
            ))
            .set_parent(spin);
    }
    (root, spin)
}

/// §owner ONE SPEAR, EVERYWHERE: the javelin's single geometry table.
///
/// The owner asked for the design to be used "consistently everywhere" -
/// viewmodel, third person, the thrown missile, any pickup. It was not:
/// the HELD spear lived in `weapon_parts` (a 1.85 m shaft, four-grey
/// palette, three cord wraps, a butt spike) and the THROWN one in
/// `spawn_spear_model` (a 0.86-unit shaft, bright `steel` blade, no
/// grip, no rivets). Two tables, two silhouettes, one weapon - and the
/// one the player watches most, the one in flight, was the plainer of
/// the two.
///
/// So there is one table now, in METRES, measured from the GRIP with
/// +Z toward the point, and both call sites read it. Neither can drift
/// from the other because there is nothing left to drift.
///
/// The design, per the owner's reference, is three things and no more:
///   a DARK LEAF BLADE with a pronounced midrib,
///   a short RED/DARK COLLAR binding blade to shaft,
///   a plain WARM-WOOD SHAFT.
struct SpearPart {
    cyl: bool,
    tone: Tone,
    /// centre, metres forward of the grip
    z: f32,
    /// across the shaft. A cylinder takes `w` as its diameter and
    /// ignores `t`; a box is `w` wide and `t` thick, which is what makes
    /// a leaf blade a blade and not a stick.
    w: f32,
    t: f32,
    /// along the shaft
    len: f32,
}

const fn sp(cyl: bool, tone: Tone, z: f32, w: f32, t: f32, len: f32) -> SpearPart {
    SpearPart { cyl, tone, z, w, t, len }
}

/// Where the THROWN spear's sim position sits along the shaft.
///
/// A javelin is drawn balanced, not nose-first: this is the point the
/// missile's `pos` lands on, and it is chosen so the head still stands
/// the same ~1.05 m ahead of the sim point it always has. Move it and
/// every spear in flight appears to lead or trail its own hitbox.
const SPEAR_MISSILE_ORIGIN_Z: f32 = 0.545;
/// The `sync_missiles` z-scale a spear slot is drawn at. The profile is
/// in metres, the missile root multiplies z by this, so the model table
/// is pre-divided by it and the two cancel exactly.
const SPEAR_MISSILE_LEN: f32 = 1.9;

fn spear_profile() -> [SpearPart; 12] {
    [
        // ---- the plain warm-wood shaft, in three collinear runs -----
        // Three rather than one so that a section is CENTRED at the
        // hand: `profile_bounds_part`/`GRIP_WINDOW_M` selects the
        // spear's bounded geometry by |z| <= 0.15, and a single 1.6 m
        // cylinder centred at z 0.65 falls outside that window - which
        // would leave the screen-intrusion sweep measuring an empty set
        // and passing vacuously. The middle run is also a hair fatter,
        // the swell a javelin has where the hand goes.
        sp(true, Tone::Wood, -0.325, 0.032, 0.032, 0.350),
        sp(true, Tone::Wood, 0.000, 0.036, 0.036, 0.300),
        sp(true, Tone::Wood, 0.655, 0.032, 0.032, 1.010),
        // ---- the collar: short, red, binding blade to shaft ---------
        sp(true, Tone::Collar, 1.200, 0.046, 0.046, 0.090),
        // ---- the leaf blade -----------------------------------------
        // Four flats that widen out of the collar, belly at the widest,
        // then taper to a point - the leaf outline, in the blocky
        // vocabulary every weapon in this game is built from.
        sp(false, Tone::Blade, 1.275, 0.052, 0.014, 0.090),
        sp(false, Tone::Blade, 1.360, 0.070, 0.014, 0.100),
        sp(false, Tone::Blade, 1.455, 0.048, 0.012, 0.110),
        sp(false, Tone::Blade, 1.545, 0.024, 0.010, 0.090),
        // THE MIDRIB, and "pronounced" is the whole brief for it: at
        // 26 mm through a 14 mm blade it stands 6 mm proud on each
        // face, so it catches light as a spine down the middle rather
        // than reading as a scratch. One tone lighter than the blade
        // for the same reason.
        sp(false, Tone::Mid, 1.375, 0.013, 0.026, 0.310),
        // and the ridge running back over the collar, so the spine
        // starts at the shaft and not in mid-air
        sp(false, Tone::Mid, 1.205, 0.013, 0.022, 0.080),
        // ---- the butt -----------------------------------------------
        // One plain dark cap and a short spike. A javelin needs weight
        // behind the hand to fly nose-first, and a shaft that simply
        // stops reads as a cut stick.
        sp(true, Tone::Blade, -0.525, 0.040, 0.040, 0.070),
        sp(true, Tone::Blade, -0.585, 0.020, 0.020, 0.060),
    ]
}

/// The THROWN spear, built from `spear_profile` - the same object the
/// player was just holding, re-anchored on its balance point.
fn spawn_spear_model(commands: &mut Commands, kit: &ModelKit) -> Entity {
    let root = commands
        .spawn((Transform::IDENTITY, Visibility::default()))
        .id();
    // `sync_missiles` scales this slot by (1, 1, SPEAR_MISSILE_LEN), so
    // only the ALONG-SHAFT numbers are pre-divided; the cross-section is
    // already in world metres and must stay there or the shaft fattens
    // in flight.
    let k = 1.0 / SPEAR_MISSILE_LEN;
    for p in spear_profile() {
        let mesh = if p.cyl { kit.cyl.clone() } else { kit.cube.clone() };
        let (rot, scale) = if p.cyl {
            (
                Quat::from_rotation_x(FRAC_PI_2),
                Vec3::new(p.w, p.len * k, p.w),
            )
        } else {
            (Quat::IDENTITY, Vec3::new(p.w, p.t, p.len * k))
        };
        commands
            .spawn((
                Mesh3d(mesh),
                MeshMaterial3d(kit.tone(p.tone)),
                Transform {
                    translation: Vec3::new(0.0, 0.0, (p.z - SPEAR_MISSILE_ORIGIN_Z) * k),
                    rotation: rot,
                    scale,
                },
            ))
            .set_parent(root);
    }
    root
}

/// How long a freshly launched rocket is drawn easing off the muzzle
/// and onto its true position. Short enough that the correction is over
/// long before the bird is anywhere near a target.
const ROCKET_LAUNCH_BLEND_S: f32 = 0.09;

/// Fletching roll rate. Fast enough to read as spin-stabilised at the
/// speeds arrows fly here, slow enough not to strobe against the frame
/// rate. Cosmetic: the sim knows nothing about it.
const ARROW_SPIN_RAD_S: f32 = 24.0;

/// Inner half-width of a red-dot window. At the ADS distance every
/// firearm settles to, this subtends roughly a ninth of screen height -
/// a real optic's proportion, big enough to aim through and small
/// enough to leave peripheral vision intact.
const OPTIC_HALF: f32 = 0.023;
/// Frame bar thickness, and the housing's fore-aft depth.
const OPTIC_FRAME: f32 = 0.005;
const OPTIC_DEPTH: f32 = 0.032;
/// Side of the emissive dot. Small on purpose: the aiming mark must not
/// cover the thing being aimed at, which is exactly how the old cross
/// failed.
const OPTIC_DOT_M: f32 = 0.0062;
/// §owner: how far the dot floats inside its window at full recoil.
///
/// This is the whole trick behind "the gun stays still and the DOT
/// moves". Bounded well inside `OPTIC_HALF` so the dot can never leave
/// the glass - a reticle that slid behind the housing would read as a
/// rendering bug, not as recoil.
const RETICLE_DRIFT_M: f32 = 0.0075;

/// §owner: the 1x RED DOT every firearm carries.
///
/// An open square housing you look THROUGH - four bars around a window,
/// never a solid block - with a thin emissive red CROSS floating at the
/// exact centre. This replaced the goalpost irons, which asked the
/// player to line up two pieces of dark grey against a dark grey world.
///
/// `y` is the reticle centre and MUST equal the gun's `sight_line_y`:
/// focus aligns that height to the eye, so any disagreement puts the
/// cross off the crosshair and the optic becomes decoration. The pairing
/// is asserted for every gun in `every_firearm_carries_an_aligned_optic`.
///
/// The cross is 1x - it moves the AIM POINT nowhere. It is a sight
/// picture, not a zoom: magnification stays whatever `zoom_deg` says.
fn push_red_dot(parts: &mut Vec<WPart>, y: f32, z: f32, mount_top: f32) {
    let outer = OPTIC_HALF + OPTIC_FRAME * 0.5;
    let span = OPTIC_HALF * 2.0 + OPTIC_FRAME * 2.0;
    debug_assert!(
        y - outer >= mount_top - 1e-4,
        "the optic's lower frame is inside the gun: window bottom {} vs          receiver top {mount_top}",
        y - outer
    );
    // housing: left / right posts, then the top and bottom bars
    parts.push(wp(false, Tone::Black, (-outer, y, z), 0.0, (OPTIC_FRAME, span, OPTIC_DEPTH)));
    parts.push(wp(false, Tone::Black, (outer, y, z), 0.0, (OPTIC_FRAME, span, OPTIC_DEPTH)));
    parts.push(wp(false, Tone::Black, (0.0, y + outer, z), 0.0, (span, OPTIC_FRAME, OPTIC_DEPTH)));
    parts.push(wp(false, Tone::Black, (0.0, y - outer, z), 0.0, (span, OPTIC_FRAME, OPTIC_DEPTH)));
    // the mount BRIDGES housing to receiver. Sized from the real gap so
    // the optic never floats and never sinks into the slide.
    let gap = (y - outer - mount_top).max(0.0);
    if gap > 1e-4 {
        parts.push(wp(
            false,
            Tone::Dark,
            (0.0, mount_top + gap * 0.5, z),
            0.0,
            (0.016, gap, OPTIC_DEPTH * 0.7),
        ));
    }
    // THE DOT - one small emissive square, dead centre.
    //
    // §owner: this was a CROSS of two long bars and it read badly - the
    // arms reached most of the way across the window, so the thing you
    // were supposed to aim WITH was also the thing covering what you
    // were aiming AT. A dot occludes almost nothing and is what a 1x
    // optic actually projects.
    //
    // It is spawned tagged rather than baked in with the housing,
    // because the dot MOVES: recoil floats it inside the window while
    // the gun body stays still (see `RETICLE_DRIFT_M` / `fp_viewmodel`).
    parts.push(wp(
        false,
        Tone::Reticle,
        (0.0, y, z),
        0.0,
        (OPTIC_DOT_M, OPTIC_DOT_M, 0.004),
    ));
}

/// §1.3: hand placements per weapon - (position, yaw, curl, mirrored) in
/// weapon-local space. Entry 0 is the GRIP socket, entry 1 (if any) the
/// FOREGRIP socket. One table serves both the viewmodel's posed hands and
/// the third-person two-bone IK, so they can never disagree.
fn weapon_hand_specs(kind: GunKind) -> Vec<(Vec3, f32, f32, bool)> {
    match kind {
        GunKind::Fists => vec![],
        // §2.2 (image 2): pistols get the two-handed CUP grip - support
        // hand wraps the firing hand from the left
        GunKind::Glock => vec![
            (Vec3::new(0.0, -0.05, -0.015), 0.0, 0.9, false),
            (Vec3::new(-0.028, -0.065, 0.005), 0.35, 0.8, true),
        ],
        GunKind::Deagle => vec![
            (Vec3::new(0.0, -0.055, -0.015), 0.0, 0.9, false),
            (Vec3::new(-0.030, -0.070, 0.005), 0.35, 0.8, true),
        ],
        GunKind::Mp5 => vec![
            (Vec3::new(0.0, -0.07, -0.055), 0.0, 1.0, false),
            (Vec3::new(0.0, -0.045, 0.16), 0.15, 0.55, true),
        ],
        GunKind::Shotgun => vec![
            (Vec3::new(0.0, -0.045, -0.06), 0.0, 1.0, false),
            (Vec3::new(0.0, -0.05, 0.30), 0.0, 0.55, true),
        ],
        GunKind::Ak47 => vec![
            (Vec3::new(0.0, -0.08, -0.06), 0.0, 1.0, false),
            (Vec3::new(0.0, -0.035, 0.32), 0.1, 0.55, true),
        ],
        GunKind::M4 => vec![
            (Vec3::new(0.0, -0.08, -0.06), 0.0, 1.0, false),
            (Vec3::new(0.0, -0.045, 0.24), 0.1, 0.55, true),
        ],
        GunKind::Awm => vec![
            (Vec3::new(0.0, -0.075, -0.10), 0.0, 1.0, false),
            (Vec3::new(0.0, -0.05, 0.26), 0.1, 0.55, true),
        ],
        GunKind::M249 => vec![
            (Vec3::new(0.0, -0.07, -0.08), 0.0, 1.0, false),
            (Vec3::new(0.0, -0.10, 0.22), 0.1, 0.55, true),
        ],
        GunKind::Bow => vec![(Vec3::new(0.0, 0.0, 0.03), 0.0, 0.8, true)],
        GunKind::Spear => vec![(Vec3::new(0.0, -0.02, 0.0), 0.0, 1.0, false)],
        // §7: rear spade grip + the side support handle - the hip carry
        GunKind::Minigun => vec![
            (Vec3::new(0.0, -0.06, -0.09), 0.0, 1.0, false),
            (Vec3::new(-0.02, -0.11, 0.18), 0.1, 0.6, true),
        ],
    }
}

